30	// GetFieldByPath retrieves a field by its path in the AST
31	func GetFieldByPath(node ast.Node, path string) (*ast.Field, bool) {
32		_, field, ok := GetNodeByPath(node, path)
33		return field, ok
34	}
35	
36	// GetNodeByPath retrieves a node by its path in the AST
37	func GetNodeByPath(node ast.Node, path string) (ast.Node, *ast.Field, bool) {
38		if path == "" || node == nil {
39			return nil, nil, false
40		}
41	
42		pathParts := strings.Split(path, ".")
43	
44		switch n := node.(type) {
45		case *ast.File:
46			startField, val, ok := lookupTopLevelField(n, pathParts[0])
47			if !ok {
48				return nil, nil, false
49			}
50			if len(pathParts) == 1 {
51				return val, startField, true
52			}
53			return traversePath(val, pathParts[1:], startField)
54	
55		case *ast.Field:
56			label := GetFieldLabel(n.Label)
57			if label == pathParts[0] {
58				if len(pathParts) == 1 {
59					return n, n, true
60				}
61				return traversePath(n.Value, pathParts[1:], n)
62			}
63			return traversePath(n.Value, pathParts, nil)
64	
65		case *ast.StructLit:
66			return traversePath(n, pathParts, nil)
67	
68		default:
69			return nil, nil, false
70		}
71	}
72	
73	// UpdateNodeByPath updates a node in the AST by its path
74	func UpdateNodeByPath(root ast.Node, path string, newExpr ast.Expr) bool {
75		_, field, ok := GetNodeByPath(root, path)
76		if !ok || field == nil {
77			return false
78		}
79		field.Value = newExpr
80		return true
81	}
82	
83	// GetFieldLabel retrieves the label of a field in the AST
84	func GetFieldLabel(label ast.Label) string {
85		if label == nil {
86			return ""
87		}
88		switch l := label.(type) {
89		case *ast.Ident:
90			return l.Name
91		case *ast.BasicLit:
92			return strings.Trim(l.Value, `"`)
93		default:
94			return ""
95		}
96	}
97	
98	// StringifyStructLitAsCueString converts a StructLit to a CUE string literal representation
99	func StringifyStructLitAsCueString(structLit *ast.StructLit) (*ast.BasicLit, error) {
100		if len(structLit.Elts) == 0 {
101			return &ast.BasicLit{
102				Kind:  token.STRING,
103				Value: `"{}"`,
104			}, nil
105		}
106	
107		formatted, err := format.Node(structLit)
108		if err != nil {
109			return nil, fmt.Errorf("failed to format struct: %w", err)
110		}
111	
112		content := string(formatted)
113	
114		content = strings.TrimSpace(content)
115		if strings.HasPrefix(content, "{") && strings.HasSuffix(content, "}") {
116			content = strings.TrimPrefix(content, "{")
117			content = strings.TrimSuffix(content, "}")
118			content = strings.Trim(content, "\n")
119		}
120	
121		if content == "" {
122			return &ast.BasicLit{
123				Kind:  token.STRING,
124				Value: `"{}"`,
125			}, nil
126		}
127		lines := strings.Split(content, "\n")
128	
129		var sb strings.Builder
130		sb.WriteString(`#"""`)
131		sb.WriteString("\n")
132		sb.WriteString(strings.Join(lines, "\n"))
133		sb.WriteString("\n")
134		sb.WriteString(`"""#`)
135	
136		result := strings.ReplaceAll(sb.String(), "\t", "  ")
137	
138		return &ast.BasicLit{
139			Kind:  token.STRING,
140			Value: result,
141		}, nil
142	}
143	
144	// ValidateCueStringLiteral validates a CUE string literal by parsing it and applying a custom validator function
145	func ValidateCueStringLiteral[T ast.Node](lit *ast.BasicLit, validator func(T) error) error {
146		if lit.Kind != token.STRING {
147			return fmt.Errorf("not a string literal")
148		}
149	
150		raw := TrimCueRawString(lit.Value)
151		if raw == "" {
152			return nil
153		}
154	
155		structLit, _, _, err := ParseCueContent(raw)
156		if err != nil {
157			return fmt.Errorf("invalid cue content in string literal: %w", err)
158		}
159	
160		node, ok := ast.Node(structLit).(T)
161		if !ok {
162			return fmt.Errorf("parsed expression is not of expected type %T", *new(T))
163		}
164		return validator(node)
165	}
166	
167	// TrimCueRawString trims a CUE raw string literal and handles escape sequences
168	func TrimCueRawString(s string) string {
169		s = strings.TrimSpace(s)
170		switch {
171		case strings.HasPrefix(s, `#"""`) && strings.HasSuffix(s, `"""#`):
172			s = strings.TrimSuffix(strings.TrimPrefix(s, `#"""`), `"""#`)
173		case strings.HasPrefix(s, `"""`) && strings.HasSuffix(s, `"""`):
174			s = strings.TrimSuffix(strings.TrimPrefix(s, `"""`), `"""`)
175		default:
176			fallback, err := strconv.Unquote(s)
177			if err == nil {
178				s = fallback
179			}
180		}
181	
182		// Handle escape sequences for backward compatibility with existing definitions
183		// For quoted strings (after strconv.Unquote): replace actual tab characters
184		s = strings.ReplaceAll(s, "\t", "  ")
185		// For raw strings (not unquoted): replace literal \t
186		s = strings.ReplaceAll(s, "\\t", "  ")
187		s = strings.ReplaceAll(s, "\\\\", "\\")
188	
189		return s
190	}
191	
192	// WrapCueStruct wraps a string in a CUE struct format
193	func WrapCueStruct(s string) string {
194		return fmt.Sprintf("{\n%s\n}", s)
195	}
196	
197	// ParseCueContent parses CUE content and extracts struct fields, skipping imports/packages
198	func ParseCueContent(content string) (*ast.StructLit, bool, bool, error) {
199		if strings.TrimSpace(content) == "" {
200			return &ast.StructLit{Elts: []ast.Decl{}}, false, false, nil
201		}
202	
203		file, err := parser.ParseFile("-", content)
204		if err != nil {
205			return nil, false, false, err
206		}
207	
208		hasImports := len(file.Imports) > 0
209		hasPackage := file.PackageName() != ""
210	
211		structLit := &ast.StructLit{
212			Elts: []ast.Decl{},
213		}
214	
215		for _, decl := range file.Decls {
216			switch decl.(type) {
217			case *ast.ImportDecl, *ast.Package:
218				// Skip imports and package declarations
219			default:
220				structLit.Elts = append(structLit.Elts, decl)
221			}
222		}
223	
224		return structLit, hasImports, hasPackage, nil
225	}
226	
227	// FindAndValidateField searches for a field at the top level or within top-level if statements
228	func FindAndValidateField(sl *ast.StructLit, fieldName string, validator fieldValidator) (found bool, err error) {
229		// First check top-level fields
230		for _, elt := range sl.Elts {
231			if field, ok := elt.(*ast.Field); ok {
232				label := GetFieldLabel(field.Label)
233				if label == fieldName {
234					found = true
235					if validator != nil {
236						err = validator(field.Value)
237					}
238					return found, err
239				}
240			}
241		}
242	
243		// If not found at top level, check within top-level if statements
244		for _, elt := range sl.Elts {
245			if comp, ok := elt.(*ast.Comprehension); ok {
246				// Check if this comprehension has if clauses (conditional fields)
247				hasIfClause := false
248				for _, clause := range comp.Clauses {
249					if _, ok := clause.(*ast.IfClause); ok {
250						hasIfClause = true
251						break
252					}
253				}
254	
255				// If it has an if clause and the value is a struct, search within it
256				if hasIfClause {
257					if structLit, ok := comp.Value.(*ast.StructLit); ok {
258						if innerFound, innerErr := FindAndValidateField(structLit, fieldName, validator); innerFound {
259							return true, innerErr
260						}
261					}
262				}
263			}
264		}
265	
266		return found, er
