29	func TestMarshalAndUnmarshalMetadata(t *testing.T) {
30		tests := []struct {
31			name               string
32			input              string
33			expectMarshalErr   string
34			expectUnmarshalErr string
35			expectContains     string
36		}{
37			{
38				name: "valid scalar values",
39				input: `
40					attributes: {
41						status: {
42							details: {
43								strVal: "ok"
44								intVal: 42
45								boolVal: true
46								nullVal: null
47								typeVal: string
48							}
49						}
50					}
51				`,
52				expectContains: "strVal",
53			},
54			{
55				name: "references to context output",
56				input: `
57					attributes: {
58						status: {
59							details: {
60								val: context.output.status.running
61							}
62						}
63					}
64				`,
65				expectContains: "val",
66			},
67			{
68				name: "valid selector and call expressions",
69				input: `
70					attributes: {
71						status: {
72							details: {
73								selector: context.output.status.running
74							}
75						}
76					}
77				`,
78				expectContains: "selector",
79			},
80			{
81				name: "struct value is invalid",
82				input: `
83					attributes: {
84						status: {
85							details: {
86								data: { key: "value" }
87							}
88						}
89					}
90				`,
91				expectMarshalErr: `unsupported expression type`,
92			},
93			{
94				name: "list value is invalid",
95				input: `
96					attributes: {
97						status: {
98							details: {
99								items: [1, 2, 3]
100							}
101						}
102					}
103				`,
104				expectMarshalErr: `unsupported expression type`,
105			},
106			{
107				name: "$key with struct is permitted",
108				input: `
109					attributes: {
110						status: {
111							details: {
112								$raw: { key: "value" }
113							}
114						}
115					}
116				`,
117				expectContains: "$raw",
118			},
119			{
120				name: "$key with list is permitted",
121				input: `
122					attributes: {
123						status: {
124							details: {
125								$items: [1, 2, 3]
126							}
127						}
128					}
129				`,
130				expectContains: "$items",
131			},
132			{
133				name: "valid stringified struct round trip",
134				input: `
135					attributes: {
136						status: {
137							details: #"""
138								ok: true
139								value: 99
140							"""#
141						}
142					}
143				`,
144				expectContains: "value",
145			},
146			{
147				name: "malformed stringified status fails validation",
148				input: `
149		        	attributes: {
