// hasDisableValidation reports whether the field carries a @disableValidation()
// attribute. It tolerates fields with no attributes and inspects every
// attribute, so it works for fields that carry multiple attributes.
func hasDisableValidation(field *ast.Field) bool {
	if field == nil {
		return false
	}
	for _, attr := range field.Attrs {
		if attr == nil {
			continue
		}
		if key, _ := attr.Split(); key == disableValidationAttr {
			return true
		}
	}
	return false
}

// marshalFieldDisableValidation stringifies a status sub-field that opts out of
