	case *ast.StructLit:
		lines, err := structContentLines(v)
		if err != nil {
			return fmt.Errorf("%s field: %w", key, err)
		}
		contentLines = lines
	case *ast.BasicLit:
		if v.Kind != token.STRING {
			return fmt.Errorf("%s field with @disableValidation must be a string or struct, got %v", key, v.Kind)
		}
		contentLines = rawStringContentLines(v.Value)
	default:
		return fmt.Errorf("%s field with @disableValidation has unsupported type %T", key, v)
	}

	statusField.Value = buildCueAttrLiteral(contentLines, statusField.Attrs)
	return nil
}

// structContentLines formats a struct literal and returns its inner declaration
// lines (without the surrounding braces), with tabs normalized to two spaces.
func structContentLines(structLit *ast.StructLit) ([]string, error) {
	if len(structLit.Elts) == 0 {
		return nil, nil
	}
	formatted, err := format.Node(structLit)
	if err != nil {
		return nil, fmt.Errorf("failed to format struct: %w", err)
	}
	content := strings.TrimSpace(string(formatted))
	if strings.HasPrefix(content, "{") && strings.HasSuffix(content, "}") {
		content = strings.TrimPrefix(content, "{")
		content = strings.TrimSuffix(content, "}")
		content = strings.Trim(content, "\n")
	}
	content = strings.ReplaceAll(content, "\t", "  ")
	if content == "" {
		return nil, nil
	}
	return strings.Split(content, "\n"), nil
}

// rawStringContentLines extracts the inner content lines of a CUE raw string
// literal value.
func rawStringContentLines(raw string) []string {
	content := strings.TrimSpace(TrimCueRawString(raw))
	if content == "" || content == "{}" {
		return nil
	}
	return strings.Split(content, "\n")
}

// buildCueAttrLiteral wraps the given content lines in a CUE raw string literal,
// prepending a "// cue-attr:@name(args)" sentinel comment for each attribute.
// Attributes whose sentinel is already present in the content are not added a
// second time, keeping the operation idempotent.
func buildCueAttrLiteral(contentLines []string, attrs []*ast.Attribute) *ast.BasicLit {
	seen := make(map[string]bool)
	for _, line := range contentLines {
		if attrText, ok := parseCueAttrLine(line); ok {
			seen[attrText] = true
		}
	}

	var sentinels []string
	for _, attr := range attrs {
		if attr == nil || seen[attr.Text] {
			continue
		}
		seen[attr.Text] = true
		sentinels = append(sentinels, cueAttrPrefix+attr.Text)
	}

	lines := append(sentinels, contentLines...)
	if len(lines) == 0 {
		return &ast.BasicLit{Kind: token.STRING, Value: `"{}"`}
	}

	var sb strings.Builder
	sb.WriteString(`#"""`)
	sb.WriteString("\n")
	sb.WriteString(strings.Join(lines, "\n"))
	sb.WriteString("\n")
	sb.WriteString(`"""#`)
	return &ast.BasicLit{Kind: token.STRING, Value: sb.String()}
