// "// cue-attr:@name(args)" sentinel comments embedded in content. Existing
// attributes that are not represented by a sentinel are preserved, and
// duplicates are removed so the restored count matches the embedded sentinels.
func restoreAttrsFromSentinels(f *ast.Field, content string) {
	seen := make(map[string]bool)
	var restored []*ast.Attribute

	for _, line := range strings.Split(content, "\n") {
		attrText, ok := parseCueAttrLine(line)
		if !ok || attrText == "" || seen[attrText] {
			continue
		}
		seen[attrText] = true
		restored = append(restored, &ast.Attribute{Text: attrText})
	}

	for _, attr := range f.Attrs {
		if attr == nil || seen[attr.Text] {
			continue
		}
		seen[attr.Text] = true
		restored = append(restored, attr)
	}

	f.Attrs = restored
}

// parseCueAttrLine returns the attribute text of a "// cue-attr:@name(args)"
// sentinel comment line, and whether the line was such a sentinel.
func parseCueAttrLine(line string) (string, bool) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, cueAttrPrefix) {
		return "", false
	}
	return strings.TrimSpace(strings.TrimPrefix(trimmed, cueAttrPrefix)), true
}

// containsCueAttrSentinel reports whether s contains at least one
// "// cue-attr:" sentinel comment line.
func containsCueAttrSentinel(s string) bool {
	for _, line := range strings.Split(s, "\n") {
		if _, ok := parseCueAttrLine(line); ok {
			return true
		}
	}
	return false
